property.value:
# Set environment variables here.

umask 0027

export JAVA_HOME={{java64_home_shell}}

if [ -z "${HBASE_CONF_DIR:-}" ]; then
  export HBASE_CONF_DIR={{hbase_conf_dir_shell}}
fi
export HBASE_CLASSPATH="${HBASE_CLASSPATH:-}"
export HBASE_LOG_DIR={{log_dir_shell}}
export HBASE_PID_DIR={{pid_dir_shell}}
export HBASE_IDENT_STRING={{hbase_user_shell}}
export HBASE_REGIONSERVERS="${HBASE_CONF_DIR}/regionservers"
export HBASE_MANAGES_ZK=false
export HBASE_JAVA_IO_TMPDIR={{java_io_tmpdir_shell}}

export SERVER_GC_OPTS="-Xlog:gc*:file=${HBASE_LOG_DIR}/${HBASE_LOGFILE:-hbase-server}.gc:time,uptime,level,tags:filecount=10,filesize=100M"
export HBASE_OPTS="${HBASE_OPTS:-} -XX:+UseG1GC -XX:MaxGCPauseMillis=100 -XX:-ResizePLAB -XX:ErrorFile=${HBASE_LOG_DIR}/hs_err_pid%p.log -Djava.io.tmpdir=${HBASE_JAVA_IO_TMPDIR}"
export HBASE_MASTER_OPTS="${HBASE_MASTER_OPTS:-} -Xmx{{master_heapsize}} -XX:ParallelGCThreads={{parallel_gc_threads}}"
export HBASE_REGIONSERVER_OPTS="${HBASE_REGIONSERVER_OPTS:-} -Xms{{regionserver_heapsize}} -Xmx{{regionserver_heapsize}} -Xmn{{regionserver_xmn_size}} -XX:ParallelGCThreads={{parallel_gc_threads}}"

# Add Kerberos authentication-related configuration
{% if security_enabled %}
export HBASE_OPTS="${HBASE_OPTS} -Djava.security.auth.login.config=${HBASE_CONF_DIR}/hbase_client_jaas.conf {{zk_security_opts}}"
export HBASE_MASTER_OPTS="${HBASE_MASTER_OPTS} -Djava.security.auth.login.config=${HBASE_CONF_DIR}/hbase_master_jaas.conf -Djavax.security.auth.useSubjectCredsOnly=false"
export HBASE_REGIONSERVER_OPTS="${HBASE_REGIONSERVER_OPTS} -Djava.security.auth.login.config=${HBASE_CONF_DIR}/hbase_regionserver_jaas.conf -Djavax.security.auth.useSubjectCredsOnly=false"
export HBASE_THRIFT_OPTS="${HBASE_THRIFT_OPTS:-} -Djava.security.auth.login.config=${HBASE_CONF_DIR}/hbase_thrift_jaas.conf -Djavax.security.auth.useSubjectCredsOnly=false"
{% endif %}

# HBase off-heap MaxDirectMemorySize
{% if hbase_max_direct_memory_size %}
export HBASE_REGIONSERVER_OPTS="${HBASE_REGIONSERVER_OPTS} -XX:MaxDirectMemorySize={{hbase_max_direct_memory_size}}m"
export HBASE_MASTER_OPTS="${HBASE_MASTER_OPTS} -XX:MaxDirectMemorySize={{hbase_max_direct_memory_size}}m"
{% endif %}
